using System;

namespace SoulComputerUse.Host;

/// <summary>The product window's client size, so the caption, the letterbox and the picture agree.</summary>
internal static class ProductWindowSize
{
    /// <summary>The client width in physical pixels.</summary>
    internal const int Width = 1200;

    /// <summary>The client height in physical pixels.</summary>
    internal const int Height = 800;
}

/// <summary>
/// The new-session mode's one argument. The session id and the binding nonce are generated by the host, so
/// no caller can supply either, and the mode takes nothing else.
/// </summary>
internal static class NewSessionArguments
{
    /// <summary>The only argument the new-session mode defines.</summary>
    internal const string Argument = "--new-session";

    /// <summary>
    /// Tells whether the command line asks for the new-session mode. Only the first argument decides, so
    /// the attach form keeps its own parsing and neither mode can silently accept the other's values.
    /// </summary>
    internal static bool IsRequested(string[] args)
    {
        ArgumentNullException.ThrowIfNull(args);
        return args.Length > 0 && string.Equals(args[0], Argument, StringComparison.Ordinal);
    }

    /// <summary>Tells whether the mode was given values it does not define.</summary>
    internal static bool HasExtraArguments(string[] args)
    {
        ArgumentNullException.ThrowIfNull(args);
        return args.Length > 1;
    }

    /// <summary>Renders the fixed usage line of the new-session mode.</summary>
    internal static string Usage()
    {
        return "Usage: SoulComputerUse.Host.exe --new-session";
    }
}